def _weapon_keyword_grant_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    sentences = [
        s for s in (_norm_rules_text(part) for part in re.split(r"[.;]\s*", _strip_html(description))) if s
    ]
    if not sentences:
        return None
    lead_prefix = r"(?:while this model is leading a unit )?"

    def _parse_keyword_labels(text_value: str) -> List[str]:
        normalized = re.sub(r"\s+", " ", str(text_value or "")).strip().lower()
        if not normalized:
            return []
        labels: List[str] = []
        patterns_local = (
            r"anti [a-z0-9 \-]+ \d+",
            r"sustained hits (?:d3|d6|\d+)",
            r"assault",
            r"devastating wounds",
            r"ignores cover",
            r"twin linked",
            r"twin-linked",
            r"lethal hits",
            r"precision",
            r"lance",
            r"heavy",
        )
        for pat in patterns_local:
            for m in re.finditer(pat, normalized, flags=re.IGNORECASE):
                token = str(m.group(0) or "").strip().lower().replace("twin linked", "twin-linked")
                if not token:
                    continue
                label = _attack_keyword_label_from_text(token)
                if label and label not in labels:
                    labels.append(label)
        return labels

    def _join_labels(labels: List[str]) -> str:
        values = [str(v or "").strip() for v in labels if str(v or "").strip()]
        if not values:
            return ""
        if len(values) == 1:
            return values[0]
        if len(values) == 2:
            return f"{values[0]} and {values[1]}"
        return f"{', '.join(values[:-1])}, and {values[-1]}"

    patterns = [
        (
            rf"{lead_prefix}(?:(?P<scope>melee|ranged) )?weapons equipped by (?:models in )?"
            r"(?:the bearers unit|that unit|this unit) (?:have|gain) (?:the )?(?P<kw_section>[a-z0-9 \-]+?) abil(?:ity|ities)",
            "unit",
        ),
        (
            rf"{lead_prefix}(?:the )?(?:bearers|this models) (?:(?P<scope>melee|ranged) )?weapons "
            r"(?:have|has|gain) (?:the )?(?P<kw_section>[a-z0-9 \-]+?) abil(?:ity|ies)",
            "bearer",
        ),
        (
            rf"{lead_prefix}(?:(?P<scope>melee|ranged) )?weapons equipped by the bearer "
            r"(?:have|has|gain) (?:the )?(?P<kw_section>[a-z0-9 \-]+?) abil(?:ity|ies)",
            "bearer",
        ),
        (
            rf"{lead_prefix}(?:(?P<scope>melee|ranged) )?weapons equipped by this model (?:have|gain) "
            r"(?:the )?(?P<kw_section>[a-z0-9 \-]+?) abil(?:ity|ies)",
            "model",
        ),
    ]
    notes: List[str] = []
    unsupported: List[str] = []
    for sentence in sentences:
        leading = sentence.startswith("while this model is leading a unit")
        prefix = "Leading: " if leading else ""
        for pattern, kind in patterns:
            m = re.fullmatch(pattern, sentence)
            if not m:
                continue
            labels = _parse_keyword_labels(m.group("kw_section") or "")
            if not labels:
                unsupported.append(str(m.group("kw_section") or ""))
                continue
            scope = (m.group("scope") or "").strip().lower()
            scope_text = "weapons"
            if scope == "melee":
                scope_text = "melee weapons"
            elif scope == "ranged":
                scope_text = "ranged weapons"
            label_text = _join_labels(labels)
            if not label_text:
                unsupported.append(str(m.group("kw_section") or ""))
                continue
            if kind == "unit":
                notes.append(f"{prefix}Unit {scope_text} gain {label_text}.")
            elif kind == "bearer":
                notes.append(f"{prefix}Bearer's {scope_text} gain {label_text}.")
            else:
                notes.append(f"{prefix}Model {scope_text} gain {label_text}.")
    if not notes and not unsupported:
        return None
    if unsupported:
        if notes:
            return ("Partial", " ".join(dict.fromkeys(notes)) + " Some weapon keywords are not supported.")
        return ("Partial", "Weapon keyword grants not supported for this keyword.")
    return ("Supported", " ".join(dict.fromkeys(notes)))


def _unit_contains_model_weapon_keyword_grant_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    sentences = [
        s for s in (_norm_rules_text(part) for part in re.split(r"[.;]\s*", _strip_html(description))) if s
    ]
    if not sentences:
        return None

    def _parse_keyword_labels(text_value: str) -> List[str]:
        normalized = re.sub(r"\s+", " ", str(text_value or "")).strip().lower()
        if not normalized:
            return []
        labels: List[str] = []
        patterns_local = (
            r"anti [a-z0-9 \-]+ \d+",
            r"sustained hits (?:d3|d6|\d+)",
            r"assault",
            r"devastating wounds",
            r"ignores cover",
            r"twin linked",
            r"twin-linked",
            r"lethal hits",
            r"precision",
            r"lance",
            r"heavy",
        )
        for pat in patterns_local:
            for match in re.finditer(pat, normalized, flags=re.IGNORECASE):
                token = str(match.group(0) or "").strip().lower().replace("twin linked", "twin-linked")
                if not token:
                    continue
                label = _attack_keyword_label_from_text(token)
                if label and label not in labels:
                    labels.append(label)
        return labels

    def _join_labels(labels: List[str]) -> str:
        values = [str(v or "").strip() for v in labels if str(v or "").strip()]
        if not values:
            return ""
        if len(values) == 1:
            return values[0]
        if len(values) == 2:
            return f"{values[0]} and {values[1]}"
        return f"{', '.join(values[:-1])}, and {values[-1]}"

    pattern = (
        r"while this unit contains an? (?P<required>[a-z0-9 '\-]+?)(?: model)? "
        r"(?:(?P<scope>melee|ranged) )?weapons equipped by models in this unit "
        r"(?:have|gain) (?:the )?(?P<kw_section>[a-z0-9 \-]+?) abil(?:ity|ities)"
    )
    notes: List[str] = []
    unsupported = False
    for sentence in sentences:
        match = re.fullmatch(pattern, sentence)
        if not match:
            continue
        labels = _parse_keyword_labels(match.group("kw_section") or "")
        if not labels:
            unsupported = True
            continue
        required = str(match.group("required") or "").strip().upper()
        scope = str(match.group("scope") or "").strip().lower()
        scope_text = "weapons"
        if scope == "melee":
            scope_text = "melee weapons"
        elif scope == "ranged":
            scope_text = "ranged weapons"
        label_text = _join_labels(labels)
        if not label_text:
            unsupported = True
            continue
        notes.append(f"While this unit contains {required}, unit {scope_text} gain {label_text}.")
    if not notes and not unsupported:
        return None
    if unsupported:
        if notes:
            return ("Partial", " ".join(dict.fromkeys(notes)) + " Some weapon keywords are not supported.")
        return ("Partial", "Conditional weapon keyword grants not supported for this keyword.")
    return ("Supported", " ".join(dict.fromkeys(notes)))


def _unit_target_keyword_weapon_keyword_grant_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    sentences: List[str] = []
    for part in re.split(r"[.;]\s*", _strip_html(description)):
        text = str(part or "").replace("\u2019", "'").replace("\u0192?T", "'")
        text = re.sub(r"'s\b", "s", text)
        text = text.lower()
        text = re.sub(r"[^a-z0-9, +\-]+", " ", text)
        text = re.sub(r"\s+", " ", text).strip()
        if text:
            sentences.append(text)
    if not sentences:
        return None

    pattern = re.compile(
        r"(?:(?P<leading>while this model is leading a unit) )?"
        r"(?:(?P<scope>melee|ranged) )?weapons equipped by models in "
        r"(?:this unit|that unit|the bearer s unit) (?:have|gain) (?:the )?"
        r"(?P<keyword>[a-z0-9 +\-]+?) ability when targeting "
        r"(?:an? )?(?:enemy )?(?P<targets>[a-z0-9, ]+?) units?",
        re.IGNORECASE,
    )
    notes: List[str] = []
    unsupported = False
    for sentence in sentences:
        match = pattern.fullmatch(sentence)
        if not match:
            continue
        keyword = _attack_keyword_label_from_text(str(match.group("keyword") or "").strip())
        if not keyword:
            unsupported = True
            continue
        target_labels: List[str] = []
        for token in re.split(r"\s*(?:,|\band\b|\bor\b)\s*", str(match.group("targets") or "").strip(), flags=re.IGNORECASE):
            label = str(token or "").strip().upper()
            if not label:
                continue
            if label.endswith("S") and len(label) > 1:
                label = label[:-1]
            if label not in target_labels:
                target_labels.append(label)
        if not target_labels:
            unsupported = True
            continue
        prefix = "Leading: " if str(match.group("leading") or "").strip() else ""
        scope = str(match.group("scope") or "").strip().lower()
        scope_text = "weapons"
        if scope == "melee":
            scope_text = "melee weapons"
        elif scope == "ranged":
            scope_text = "ranged weapons"
        notes.append(f"{prefix}Unit {scope_text} gain {keyword} while targeting {'/'.join(target_labels)} units.")
    if not notes and not unsupported:
        return None
    if unsupported:
        if notes:
            return ("Partial", " ".join(dict.fromkeys(notes)) + " Some weapon keywords are not supported.")
        return ("Partial", "Conditional weapon keyword grants not supported for this keyword.")
    return ("Supported", " ".join(dict.fromkeys(notes)))


def _unit_melee_weapon_ap_bonus_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    match = re.fullmatch(
        r"(?:(?P<leading>while this model is leading a unit) )?"
        r"improve the armou?r penetration characteristic of melee weapons equipped by models in "
        r"(?:this unit|that unit|the bearer s unit) by (?P<bonus>\d+)",
        norm,
    )
    if not match:
        return None
    try:
        bonus = int(match.group("bonus") or 0)
    except (TypeError, ValueError):
        bonus = 0
    if bonus <= 0:
        return None
    prefix = "Leading: " if str(match.group("leading") or "").strip() else ""
    return ("Supported", f"{prefix}Unit melee weapons improve AP by {bonus}.")


