def _unit_contains_advance_charge_heroic_intervention_zero_cp_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    if "heroic intervention" not in norm or "0cp" not in norm:
        return None
    match = re.search(
        r"while\s+(?:the\s+bearer\s+unit|that\s+unit|this\s+unit|this\s+model\s+unit)\s+contains\s+an?\s+"
        r"(?P<model>[a-z0-9' -]+?)\s*,?\s*add\s+(?P<value>\d+)\s+to\s+advance\s+and\s+charge\s+rolls?\s+made\s+for\s+"
        r"(?:the\s+bearer\s+unit|that\s+unit|this\s+unit|this\s+model\s+unit)\s+and\s+you\s+can\s+target\s+"
        r"(?:the\s+bearer\s+unit|that\s+unit|this\s+unit|this\s+model\s+unit)\s+with\s+the\s+heroic\s+intervention\s+stratagem\s+for\s+0cp",
        norm,
        flags=re.IGNORECASE,
    )
    if not match:
        return None
    model = re.sub(r"\s+", " ", str(match.group("model") or "").strip())
    value = str(match.group("value") or "").strip()
    if not model or not value:
        return None
    return (
        "Supported",
        f"While the attached unit contains {model}, Advance and Charge rolls for that unit get +{value} and Heroic Intervention can target that unit for 0CP.",
    )


def _targeted_stratagem_cp_refund_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None

    bonus_clause = (
        r"(?:adding (?P<bonus>\d+) to the result if there (?:are|is) one or more friendly "
        r"(?P<bonus_keyword>[a-z0-9 ]+?) models? within (?P<bonus_range>\d+) )?"
    )
    direct_pattern = (
        r"(?:the bearer loses the smoke keyword but )?each time you target "
        r"(?:this unit|that unit|the bearer|the bearers unit|the bearer s unit|this models unit|this model s unit) "
        r"with a stratagem roll one d6 "
        + bonus_clause +
        r"on a (?P<roll>\d+) (?:you )?gain (?P<cp>\d+) ?cp"
    )
    select_pattern = (
        r"each time you select "
        r"(?:the bearers unit|the bearer s unit|this models unit|this model s unit|its unit|that unit|this unit) "
        r"as the target of a stratagem roll one d6 "
        + bonus_clause +
        r"on a (?P<roll>\d+) (?:you )?gain (?P<cp>\d+) ?cp"
    )
    aura_pattern = (
        r"while a friendly (?P<keyword>[a-z0-9 ]+?) unit is within (?P<range>\d+) of (?:this model|the bearer) "
        r"each time you (?:target that unit with a stratagem|select that unit as the target of a stratagem) roll one d6 "
        + bonus_clause +
        r"on a (?P<roll>\d+) (?:you )?gain (?P<cp>\d+) ?cp"
    )
    smoke_loss = "bearer loses the smoke keyword" in norm
    m_aura = re.fullmatch(aura_pattern, norm)
    if m_aura:
        roll = m_aura.group("roll") or "5"
        cp = m_aura.group("cp") or "1"
        keyword = re.sub(r"\s+", " ", str(m_aura.group("keyword") or "").strip()).upper()
        range_value = m_aura.group("range") or "0"
        bonus = m_aura.group("bonus")
        bonus_keyword = re.sub(r"\s+", " ", str(m_aura.group("bonus_keyword") or "").strip()).upper()
        bonus_range = m_aura.group("bonus_range") or "0"
        bonus_note = ""
        if bonus:
            bonus_note = f", adding {bonus} if one or more friendly {bonus_keyword} models are within {bonus_range}\""
        return (
            "Supported",
            f"Aura: friendly {keyword} units within {range_value}\" roll D6{bonus_note} when targeted by a Stratagem and gain {cp} CP on {roll}+ (CP gain guardrail respected).",
        )
    for pattern in (direct_pattern, select_pattern):
        m = re.fullmatch(pattern, norm)
        if not m:
            continue
        roll = m.group("roll") or "5"
        cp = m.group("cp") or "1"
        bonus = m.group("bonus")
        bonus_keyword = re.sub(r"\s+", " ", str(m.group("bonus_keyword") or "").strip()).upper()
        bonus_range = m.group("bonus_range") or "0"
        bonus_note = ""
        if bonus:
            bonus_note = f", adding {bonus} if one or more friendly {bonus_keyword} models are within {bonus_range}\""
        if smoke_loss:
            return (
                "Supported",
                f"Bearer loses the SMOKE keyword; when targeted by a Stratagem, roll D6{bonus_note} and gain {cp} CP on {roll}+ (CP gain guardrail respected).",
            )
        return (
            "Supported",
            f"When targeted by a Stratagem, roll D6{bonus_note} and gain {cp} CP on {roll}+ (CP gain guardrail respected).",
        )
    return None


