def _leading_unit_common_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    text = _strip_html(description)
    text = text.replace("\u2019", "'").replace("\u0192?T", "'")
    text = re.sub(r"\s+", " ", text).strip()
    if not text:
        return None
    low = text.lower()
    if not re.search(r"while this model is leading(?:s)?(?: a)? .*? unit", low, flags=re.IGNORECASE):
        return None
    if (
        "model in that unit" not in low
        and "models in that unit" not in low
        and "that unit has" not in low
        and "that unit have" not in low
    ):
        return None

    normalized = _norm_rules_text(text)
    unmodified_pattern = (
        r"while this model is leading a unit once per phase you can change the result of one hit roll one wound roll or one "
        r"damage roll made for a model in that unit(?: excluding support weapon models)? to an unmodified 6"
    )
    if re.fullmatch(unmodified_pattern, normalized):
        note = "Leading: once per phase, can set one Hit/Wound/Damage roll to an unmodified 6."
        if "excluding support weapon models" in normalized:
            note = "Leading: once per phase, can set one Hit/Wound/Damage roll to an unmodified 6 (excluding Support Weapon models)."
        return ("Supported", note)
    overlord_pattern = (
        r"while this model is leading a unit each time a model in that unit makes an attack reroll a wound roll of 1 "
        r"while that unit is below its starting strength each time a model in that unit makes an attack you can reroll the wound roll instead"
    )
    if re.fullmatch(overlord_pattern, normalized):
        return (
            "Supported",
            "Leading: re-roll Wound rolls of 1; while below Starting Strength, re-roll the Wound roll instead.",
        )
    notes: List[str] = []
    lethal_melee = re.search(
        r"melee weapons equipped by models in that unit have the \[?lethal hits\]? ability",
        low,
        flags=re.IGNORECASE,
    )
    lethal_ranged = re.search(
        r"ranged weapons equipped by models in that unit have the \[?lethal hits\]? ability",
        low,
        flags=re.IGNORECASE,
    )
    lethal_any = re.search(
        r"weapons equipped by models in that unit have the \[?lethal hits\]? ability",
        low,
        flags=re.IGNORECASE,
    )
    if lethal_melee:
        notes.append("Leading: unit melee weapons gain Lethal Hits.")
    elif lethal_ranged:
        notes.append("Leading: unit ranged weapons gain Lethal Hits.")
    elif lethal_any:
        notes.append("Leading: unit weapons gain Lethal Hits.")
    crit_hit_match = re.search(
        r"a critical hit is scored on an unmodified hit roll of (\d)\+?(?: instead of only a 6)?",
        low,
        flags=re.IGNORECASE,
    )
    if crit_hit_match:
        notes.append(f"Leading: attacks score Critical Hits on unmodified {crit_hit_match.group(1)}+.")

    fight_first_match = re.search(
        r"(?:models in that unit|that unit)\s+(?:has|have)\s+(?:the\s+)?fights?\s+first\s+ability",
        low,
        flags=re.IGNORECASE,
    )
    if fight_first_match:
        notes.append("Leading: unit gains Fights First.")
    scout_match = re.search(
        r"(?:models in that unit|that unit)\s+(?:has|have)\s+(?:the\s+)?scouts?\s+(?P<rng>\d+)\s*\"?\s+ability",
        low,
        flags=re.IGNORECASE,
    )
    if scout_match:
        if "unless that unit starts the battle embarked within a transport" in low:
            notes.append(
                f"Leading: attached unit gains Scouts {scout_match.group('rng')}\" unless it started the battle embarked in a TRANSPORT."
            )
        else:
            notes.append(f"Leading: unit gains Scouts {scout_match.group('rng')}\".")

    invuln_psychic_daemon_match = re.search(
        r"models in that unit have (?:a|the)?\s*(\d)\+\s*invulnerable save,?\s*and\s*(?:a|the)?\s*(\d)\+\s*invulnerable save against psychic attacks and attacks made by daemon models",
        low,
        flags=re.IGNORECASE,
    )
    invuln_ranged_match = re.search(
        r"models in that unit have (?:a|the)?\s*(\d)\+\s*invulnerable save against ranged attacks",
        low,
        flags=re.IGNORECASE,
    )
    invuln_match = re.search(
        r"models in that unit have (?:a|the)?\s*(\d)\+\s*invulnerable save",
        low,
        flags=re.IGNORECASE,
    )
    if invuln_psychic_daemon_match:
        notes.append(
            "Leading: unit models gain "
            f"{invuln_psychic_daemon_match.group(1)}+ invulnerable save "
            f"({invuln_psychic_daemon_match.group(2)}+ vs Psychic attacks and attacks made by DAEMON models)."
        )
    elif invuln_ranged_match:
        notes.append(f"Leading: unit models gain {invuln_ranged_match.group(1)}+ invulnerable save against ranged attacks.")
    elif invuln_match:
        notes.append(f"Leading: unit models gain {invuln_match.group(1)}+ invulnerable save.")
    if re.search(
        r"(?:models in that unit|models in this unit|that unit|this unit) (?:has|have) the benefit of cover",
        low,
        flags=re.IGNORECASE,
    ):
        notes.append("Leading: unit gains Benefit of Cover against ranged attacks.")

    if "melee attack" in low:
        attack_scope = "melee"
    elif "ranged attack" in low:
        attack_scope = "ranged"
    else:
        attack_scope = "all"

    hit_conditional = False
    wound_conditional = False
    m = re.search(
        r"add\s+(\d+)\s+to\s+the\s+hit\s+roll\s+if\s+that\s+unit\s+is\s+below\s+(?:its\s+)?starting\s+strength",
        low,
        flags=re.IGNORECASE,
    )
    if m:
        hit_conditional = True
        notes.append(f"Leading: +{m.group(1)} to hit for {attack_scope} attacks while below Starting Strength.")
    m = re.search(
        r"add\s+(\d+)\s+to\s+the\s+wound\s+roll(?:\s+as\s+well)?\s+if\s+that\s+unit\s+is\s+below\s+half[- ]strength",
        low,
        flags=re.IGNORECASE,
    )
    if m:
        wound_conditional = True
        notes.append(f"Leading: +{m.group(1)} to wound for {attack_scope} attacks while below Half-strength.")
    m = re.search(
        r"add\s+(\d+)\s+to\s+the\s+wound\s+roll(?:\s+as\s+well)?\s+if\s+the\s+target\s+is\s+battle[- ]shocked",
        low,
        flags=re.IGNORECASE,
    )
    if not m:
        m = re.search(
            r"if\s+the\s+target\s+is\s+battle[- ]shocked,\s+add\s+(\d+)\s+to\s+the\s+wound\s+roll",
            low,
            flags=re.IGNORECASE,
        )
    if m:
        wound_conditional = True
        notes.append(f"Leading: +{m.group(1)} to wound for {attack_scope} attacks vs Battle-shocked targets.")
    m = re.search(
        r"each time a model in that unit makes (?:a|an)\s+(?:melee|ranged)?\s*attack, add\s+(\d+)\s+to\s+the\s+hit\s+roll\s+and\s+add\s+(\d+)\s+to\s+the\s+wound\s+roll",
        low,
        flags=re.IGNORECASE,
    )
    if m:
        hit_conditional = True
        wound_conditional = True
        notes.append(f"Leading: +{m.group(1)} to hit for {attack_scope} attacks.")
        notes.append(f"Leading: +{m.group(2)} to wound for {attack_scope} attacks.")

    if not hit_conditional:
        m = re.search(
            r"each time a model in that unit makes (?:a|an)\s+(?:melee|ranged)?\s*attack, add\s+(\d+)\s+to\s+the\s+hit\s+roll",
            low,
            flags=re.IGNORECASE,
        )
        if m:
            notes.append(f"Leading: +{m.group(1)} to hit for {attack_scope} attacks.")

    if not wound_conditional:
        m = re.search(
            r"each time a model in that unit makes (?:a|an)\s+(?:melee|ranged)?\s*attack, add\s+(\d+)\s+to\s+the\s+wound\s+roll",
            low,
            flags=re.IGNORECASE,
        )
        if m:
            notes.append(f"Leading: +{m.group(1)} to wound for {attack_scope} attacks.")
    defensive_wound_match = re.search(
        r"each time an attack targets that unit subtract (\d+) from the wound roll",
        low,
        flags=re.IGNORECASE,
    )
    if defensive_wound_match:
        notes.append(f"Leading: attackers suffer -{defensive_wound_match.group(1)} to wound against the unit.")

    hit_re = re.search(r"re-?roll (?:a|any)?\s*hit roll(?:s)? of 1", low, flags=re.IGNORECASE)
    wound_re = re.search(r"re-?roll (?:a|any)?\s*wound roll(?:s)? of 1", low, flags=re.IGNORECASE)
    if hit_re and wound_re:
        notes.append(f"Leading: re-roll Hit/Wound rolls of 1 for {attack_scope} attacks.")

    normalized_sentences = []
    for sentence in re.split(r"[.;]\s*", _strip_html(description)):
        norm_sentence = _norm_rules_text(sentence)
        if norm_sentence:
            normalized_sentences.append(norm_sentence)

    lead_prefix = r"(?:while this model is leading(?:s)?(?: a)? .*? unit )?"
    patterns = [
        rf"{lead_prefix}melee weapons equipped by models in that unit have the lethal hits ability",
        rf"{lead_prefix}ranged weapons equipped by models in that unit have the lethal hits ability",
        rf"{lead_prefix}weapons equipped by models in that unit have the lethal hits ability",
        rf"{lead_prefix}(?:models in that unit|that unit) (?:has|have) (?:the )?fights? first ability",
        rf"{lead_prefix}(?:unless that unit starts the battle embarked within a transport )?(?:models in that unit|that unit) (?:has|have) (?:the )?scouts? \d+ ability",
        rf"{lead_prefix}each time a model in that unit makes (?:a|an)?(?: melee| ranged)? attack(?:s)? add \d+ to the hit roll if that unit is below (?:its )?starting strength and add \d+ to the wound roll(?: as well)? if that unit is below (?:its )?half strength",
        rf"{lead_prefix}each time a model in that unit makes (?:a|an)?(?: melee| ranged)? attack add \d+ to the hit roll and add \d+ to the wound roll",
        rf"{lead_prefix}each time a model in that unit makes (?:a|an)?(?: melee| ranged)? attack add \d+ to the hit roll",
        rf"{lead_prefix}each time a model in that unit makes (?:a|an)?(?: melee| ranged)? attack add \d+ to the wound roll",
        rf"{lead_prefix}each time an attack targets that unit subtract \d+ from the wound roll",
        rf"{lead_prefix}add \d+ to the hit roll if that unit is below (?:its )?starting strength",
        rf"{lead_prefix}add \d+ to the wound roll(?: as well)? if that unit is below half strength",
        rf"{lead_prefix}add \d+ to the wound roll(?: as well)? if the target is battle shocked",
        rf"{lead_prefix}if the target is battle shocked add \d+ to the wound roll(?: as well)?",
        rf"{lead_prefix}models in that unit have (?:a|the)?\s*\d+ invulnerable save,?\s*and\s*(?:a|the)?\s*\d+ invulnerable save against psychic attacks and attacks made by daemon models",
        rf"{lead_prefix}models in that unit have (?:a|the)?\s*\d+ invulnerable save against ranged attacks",
        rf"{lead_prefix}models in that unit have (?:a|the)?\s*\d+ invulnerable save",
        rf"{lead_prefix}(?:models in that unit|that unit) have the benefit of cover",
        rf"{lead_prefix}(?:models in that unit|that unit) has the benefit of cover",
        rf"{lead_prefix}(?:in addition )?each time a model in that unit makes an attack a critical hit is scored on an unmodified hit roll of \d\+?(?: instead of only a 6)?",
        rf"{lead_prefix}.*reroll .*hit roll.* of 1.*",
        rf"{lead_prefix}.*reroll .*wound roll.* of 1.*",
    ]

    unsupported = [
        s for s in normalized_sentences
        if not any(re.fullmatch(p, s) for p in patterns)
    ]

    if notes:
        status = "Supported" if not unsupported else "Partial"
        return (status, " ".join(notes))
    return None


def _leading_scaled_weapon_bonus_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    attacks_match = re.fullmatch(
        r"while this model is leading a unit add (?P<bonus>\d+) to the attacks characteristic of (?:this model s|this models) "
        r"(?P<weapon>[a-z0-9 ' -]+?) weapon for every (?P<step>\d+) models in that unit(?: rounding down)? "
        r"but while that unit contains (?P<hazard>\d+) or more models that weapon has the hazardous ability",
        norm,
    )
    if attacks_match:
        weapon = " ".join(str(attacks_match.group("weapon") or "").strip().split())
        return (
            "Supported",
            f"Leading: this model's {weapon} gains +{attacks_match.group('bonus')}A per {attacks_match.group('step')} models in the unit, and gains [HAZARDOUS] at {attacks_match.group('hazard')}+ models.",
        )
    strength_damage_match = re.fullmatch(
        r"while this model is leading a unit add (?P<bonus>\d+) to the (?:(?:strength and damage)|(?:damage and strength)) "
        r"characteristics of (?:this model s|this models) (?P<weapon>[a-z0-9 ' -]+?) weapon for every (?P<step>\d+) models in that unit"
        r"(?: rounding down)? but while that unit contains (?P<hazard>\d+) or more models that weapon has the hazardous ability",
        norm,
    )
    if not strength_damage_match:
        return None
    weapon = " ".join(str(strength_damage_match.group("weapon") or "").strip().split())
    return (
        "Supported",
        f"Leading: this model's {weapon} gains +{strength_damage_match.group('bonus')}S/+{strength_damage_match.group('bonus')}D per {strength_damage_match.group('step')} models in the unit, and gains [HAZARDOUS] at {strength_damage_match.group('hazard')}+ models.",
    )


def _start_any_phase_enemy_range_mortal_threshold_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    m = re.fullmatch(
        r"once per battle at the start of any phase (?:you can )?select one enemy unit within (?P<range>\d+) of "
        r"(?:this model|the bearer) "
        r"and roll (?:one|1) d6 on a (?P<threshold>\d)\+? that enemy unit suffers (?P<mw>\d*d\d+(?:\+\d+)?|\d+) mortal wounds?"
        r"(?: or (?P<alt_mw>\d*d\d+(?:\+\d+)?|\d+) mortal wounds? instead if it is a (?P<alt_keywords>[a-z0-9 ]+?) unit)?"
        r"(?: designer(?:s| s)? note .*)?",
        norm,
    )
    if not m:
        return None
    note = (
        f"Start of any phase optional selection: choose one enemy unit within {m.group('range')}\"; on {m.group('threshold')}+ "
        f"it suffers {str(m.group('mw') or '').upper()} mortal wounds. Once per battle."
    )
    alt_mw = str(m.group("alt_mw") or "").strip().upper()
    alt_keywords_raw = str(m.group("alt_keywords") or "").strip()
    if alt_mw and alt_keywords_raw:
        alt_keywords = [
            str(token or "").strip().upper()
            for token in re.split(r"\s+(?:or|and)\s+", alt_keywords_raw)
            if str(token or "").strip()
        ]
        if alt_keywords:
            note += f" {('/'.join(alt_keywords))} targets instead suffer {alt_mw} mortal wounds."
    return (
        "Supported",
        note,
    )


