def _leading_keyword_unit_target_hit_penalty_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    text = _strip_html(description)
    text = text.replace("\u2019", "'").replace("\u0192?T", "'")
    text = re.sub(r"\s+", " ", text).strip().lower()
    if not text:
        return None
    pattern = re.compile(
        r"^while an? (?P<keyword>[a-z0-9 ]+) model is leading this unit, each time (?:a|an) "
        r"(?:(?P<atype>melee|ranged) )?attack(?:s)? (?:targets|is made against) this unit, subtract 1 from the hit roll\.?$",
        re.IGNORECASE,
    )
    match = pattern.match(text)
    if not match:
        return None
    attack_type = str(match.group("atype") or "").strip().lower()
    keyword = str(match.group("keyword") or "").strip().upper()
    if attack_type == "melee":
        scope_text = "melee"
    elif attack_type == "ranged":
        scope_text = "ranged"
    else:
        scope_text = "all"
    return (
        "Supported",
        f"Unit targeted: -1 to hit vs {scope_text} attacks while led by a {keyword} model.",
    )


def _target_hit_roll_penalty_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    text = _strip_html(description)
    text = text.replace("\u2019", "'").replace("\u0192?T", "'")
    text = re.sub(r"\s+", " ", text).strip()
    if not text:
        return None
    text = re.sub(r";\s*", ". ", text)
    sentences = [part.strip() for part in re.split(r"\.\s*", text) if part.strip()]
    if not sentences:
        return None

    prefix = r"(?:while this (?:model|unit) is leading (?:a|this) unit, )?"
    unit_re = re.compile(
        prefix
        + r"each time (?:a|an) (?:(?P<atype>melee|ranged) )?attack "
        r"(?:targets|is made against) (?:this unit|that unit|the bearer'?s unit), subtract 1 from the hit roll(?P<tail>.*)$",
        re.IGNORECASE,
    )
    model_re = re.compile(
        prefix
        + r"each time (?:a|an) (?:(?P<atype>melee|ranged) )?attack "
        r"(?:targets|is made against) this model, subtract 1 from the hit roll(?P<tail>.*)$",
        re.IGNORECASE,
    )

    matched: List[str] = []
    notes: List[str] = []
    partial = False

    def _note(scope: str, atype: Optional[str]) -> None:
        if atype == "melee":
            scope_text = "melee"
        elif atype == "ranged":
            scope_text = "ranged"
        else:
            scope_text = "all"
        notes.append(f"{scope} targeted: -1 to hit vs {scope_text} attacks.")

    for sentence in sentences:
        sl = sentence.lower()
        if not sl.startswith("each time"):
            continue
        if any(x in f" {sl} " for x in (" if ", " unless ", " while ", " when ")):
            continue
        for scope, pattern in (("Unit", unit_re), ("Model", model_re)):
            m = pattern.match(sl)
            if not m:
                continue
            matched.append(sentence)
            _note(scope, (m.group("atype") or "").lower() or None)
            tail = (m.group("tail") or "").strip().strip(" .;")
            if tail:
                partial = True
            break

    if not matched:
        return None

    if any(s for s in sentences if s not in matched):
        partial = True

    status = "Partial" if partial else "Supported"
    return (status, " ".join(notes) if notes else "-1 to hit when targeted.")


def _model_attack_skill_override_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    m = re.fullmatch(
        r"the bearers (?P<attack_type>ranged|melee) weapons have a (?P<label>ballistic|weapon) skill characteristic of (?P<value>\d+)\+?",
        norm,
    )
    if not m:
        return None
    attack_type = str(m.group("attack_type") or "").strip().lower()
    label = str(m.group("label") or "").strip().lower()
    value = str(m.group("value") or "").strip()
    if attack_type == "ranged" and label != "ballistic":
        return None
    if attack_type == "melee" and label != "weapon":
        return None
    skill_label = "BS" if attack_type == "ranged" else "WS"
    return (
        "Supported",
        f"Bearer’s {attack_type} weapons use {skill_label} {value}+.",
    )


def _enemy_aura_attack_hit_wound_penalty_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    m_psychological = re.fullmatch(
        r"while an enemy unit(?: excluding [a-z0-9 ]+)? is within (?P<range>\d+) of this model if that unit is battle shocked "
        r"each time a model in that unit makes an attack subtract (?P<hit>\d+) from the hit roll "
        r"each time a friendly (?P<friendly>[a-z0-9 ]+) model makes an attack that targets that unit add (?P<wound>\d+) to the wound roll",
        norm,
    )
    if m_psychological:
        rng = m_psychological.group("range") or "?"
        hit = m_psychological.group("hit") or "1"
        wound = m_psychological.group("wound") or "1"
        friendly = str(m_psychological.group("friendly") or "friendly").strip().upper()
        return (
            "Supported",
            f"Enemy units within {rng}\" that are Battle-shocked suffer -{hit} to Hit rolls, and friendly {friendly} models gain +{wound} to Wound rolls when targeting those units.",
        )

    m = re.fullmatch(
        r"while an enemy unit(?: excluding [a-z0-9 ]+)? is within (?P<range>\d+) of this model each time a model in that unit makes an attack "
        r"subtract (?P<hit>\d+) from the hit roll"
        r"(?: and if that enemy unit is below half strength subtract (?P<wound>\d+) from the wound roll as well)?",
        norm,
    )
    if not m:
        return None
    rng = m.group("range") or "?"
    hit = m.group("hit") or "1"
    wound = m.group("wound")
    if wound:
        return (
            "Supported",
            f"Enemy units within {rng}\" suffer -{hit} to Hit rolls, and if those enemy units are Below Half-strength they also suffer -{wound} to Wound rolls.",
        )
    return ("Supported", f"Enemy units within {rng}\" suffer -{hit} to Hit rolls.")


