def _post_deployment_redeploy_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"(?:if your army includes this model |if your army (?:includes|contains) one or more (?:units|models) with this ability )?"
        r"after both players have deployed their armies "
        r"(?:if (?:this unit|the bearer|this model) is on the battlefield "
        r"(?:or any transport it is embarked within is on the battlefield )?)?"
        r"(?:you can )?select(?: up ?to)? (?P<count>\d+|one|two|three|four|five|six|d3(?: \+ \d+)?) "
        r"(?P<filter>[a-z0-9 ']+?) units? from your army and redeploy(?: all of those units| them| it)?(?: (?P<tail>.*))?"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None
    count = str(m.group("count") or "").strip().upper()
    if not count:
        count = "3"
    unit_filter = str(m.group("filter") or "").strip().upper()
    if not unit_filter:
        unit_filter = "friendly"
    tail = str(m.group("tail") or "").strip()
    note = f"After deployment: redeploy up to {count} {unit_filter} unit(s)."
    if (
        "if this unit is on the battlefield" in norm
        or "if the bearer is on the battlefield" in norm
        or "if this model is on the battlefield" in norm
    ):
        note = (
            f"After deployment: while the source is on the battlefield (or a Transport it is embarked within "
            f"is on the battlefield), redeploy up to {count} {unit_filter} unit(s)."
        )
    if "strategic reserves" in tail or "strategic reserves" in norm:
        note = f"{note} Selected units can be placed into Strategic Reserves regardless of normal limits."
    return ("Supported", note)


def _sticky_objective_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    legacy = (
        r"at the end of your command phase if this unit is within range of an objective marker you control "
        r"that objective marker remains under your control even if you have no models within range of it "
        r"until your opponent controls it"
    )
    legacy_timed = (
        r"at the end of your command phase if this unit is within range of an objective marker you control "
        r"that objective marker remains under your control even if you have no models within range of it "
        r"until your opponent controls it at (?:the )?start or end of any turn"
    )
    legacy_timed_control = (
        r"if you control an objective marker at the end of your command phase and this unit is within range of that objective marker "
        r"that objective marker remains under your control even if you have no models within range of it "
        r"until your opponent controls it at (?:the )?start or end of any turn"
    )
    leading_timed_it = (
        r"while this model is leading a unit at the end of your command phase if that unit is within range of an objective marker you control "
        r"it remains under your control even if you have no models within range of it "
        r"until your opponent controls it at (?:the )?start or end of any turn"
    )
    loc = (
        r"at the end of your command phase if this unit is within range of an objective marker you control "
        r"that objective marker remains under your control until your opponents level of control over that "
        r"objective marker is greater than yours at the end of a phase"
    )
    loc_control = (
        r"at the end of your command phase if you control an objective marker that this unit "
        r"(?:or a transport it is embarked within )?is within range of that objective marker remains under your control "
        r"until your opponents level of control over that objective marker is greater than yours at the end of a phase"
    )
    if not (
        re.fullmatch(legacy, norm)
        or re.fullmatch(legacy_timed, norm)
        or re.fullmatch(legacy_timed_control, norm)
        or re.fullmatch(leading_timed_it, norm)
        or re.fullmatch(loc, norm)
        or re.fullmatch(loc_control, norm)
    ):
        return None
    if re.fullmatch(leading_timed_it, norm):
        return ("Supported", "While leading, end of Command phase: objective becomes sticky while you controlled it.")
    return ("Supported", "End of Command phase: objective becomes sticky while you controlled it.")


def _command_phase_bodyguard_return_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    if "command phase" not in norm:
        return None
    if "bodyguard model" not in norm and "bodyguard models" not in norm:
        return None
    if "return" not in norm or "destroyed" not in norm:
        return None
    if "not leading a unit" in norm:
        return None
    if (
        "leading a unit" not in norm
        and "leading this unit" not in norm
        and "bearer is leading a unit" not in norm
    ):
        return None
    if "can return" not in norm:
        return None

    amount_match = re.search(
        r"return(?: up to)? (?P<amt>one|a|\d+|(?:\d+)?d\d+(?: \d+)?) destroyed bodyguard models?",
        norm,
    )
    if amount_match is None:
        return None
    token = str(amount_match.group("amt") or "").strip().lower()
    up_to = "up to " if "up to" in str(amount_match.group(0) or "").lower() else ""

    amount_label = ""
    if token in {"one", "a"}:
        amount_label = "1"
    elif token.isdigit():
        amount_label = str(int(token))
    else:
        dice_match = re.fullmatch(r"(?:(?P<count>\d+))?d(?P<faces>\d+)(?: (?P<modifier>\d+))?", token)
        if dice_match is None:
            amount_label = token.upper()
        else:
            count = int(dice_match.group("count") or 1)
            faces = int(dice_match.group("faces") or 0)
            modifier = int(dice_match.group("modifier") or 0)
            if faces <= 0:
                return None
            amount_label = f"{count}D{faces}" if count != 1 else f"D{faces}"
            if modifier > 0:
                amount_label = f"{amount_label}+{modifier}"
    if not amount_label:
        return None

    note = (
        f"Command phase while leading: return {up_to}{amount_label} destroyed Bodyguard model(s) "
        f"(capped at starting strength)."
    )
    if "below starting strength" in norm or "below its starting strength" in norm:
        note = f"{note} Requires bearer/unit below Starting Strength."
    if bool(re.search(r"\bonce per battle\b", norm)) and "once per battle round" not in norm:
        note = f"{note} Once per battle."
    return (
        "Supported",
        note,
    )


