def _strategic_reserves_early_arrival_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    selected_friendly_pattern = (
        r"once per battle round in your movement phase you can select one friendly (?P<keyword>[a-z0-9 ]+) unit that is in reserves "
        r"if you do until the end of the phase for the purpose of setting up that unit on the battlefield treat the current battle round number "
        r"as being one higher than it actually is"
    )
    m_selected = re.fullmatch(selected_friendly_pattern, norm)
    if m_selected:
        keyword_phrase = str(m_selected.group("keyword") or "").strip().upper()
        return (
            "Supported",
            f"Movement phase: once per battle round select one friendly {keyword_phrase} unit in Reserves; until end of phase treat the battle round as +1 for its setup.",
        )

    round_bonus_pattern = (
        r"if this (?:unit|model) starts the game in strategic reserves it can be set up in the reinforcements step of your first "
        r"second or third movement phase(?: regardless of any mission rules)? if this (?:unit|model) is in strategic reserves "
        r"for the purposes of setting up this (?:unit|model) on the battlefield treat the (?:current )?battle round number "
        r"as being one higher than it actually is"
    )
    if re.fullmatch(round_bonus_pattern, norm):
        return (
            "Supported",
            "Strategic Reserves: may arrive in battle rounds 1-3; treat battle round as +1 when setting up.",
        )

    hover_mode_pattern = (
        r"if this (?:unit|model) starts the game in hover mode and (?:in|is in) strategic reserves it can be set up in the reinforcements "
        r"step of your first second or third movement phase(?: regardless of any mission rules)?"
    )
    if re.fullmatch(hover_mode_pattern, norm):
        return (
            "Supported",
            "Strategic Reserves: may arrive in battle rounds 1-3 if it started in Hover mode and in Strategic Reserves.",
        )

    direct_early_arrival_pattern = (
        r"if this (?:unit|model) starts the game in strategic reserves it can be set up in the reinforcements step of your first "
        r"second or third movement phase(?: regardless of any mission rules)?"
    )
    if re.fullmatch(direct_early_arrival_pattern, norm):
        return (
            "Supported",
            "Strategic Reserves: may arrive in battle rounds 1-3 regardless of mission restrictions.",
        )

    direct_self_arrival_pattern = (
        r"this (?:unit|model) can be set up in the reinforcements step of your first second or third movement phase"
        r"(?: regardless of any mission rules)?"
    )
    if re.fullmatch(direct_self_arrival_pattern, norm):
        return (
            "Supported",
            "Reserves arrivals: may be set up in battle rounds 1-3 regardless of mission restrictions.",
        )
    return None


def _transport_assault_reserves_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    if "must start the battle in reserves" not in norm:
        return None
    if "reinforcements step" not in norm:
        return None
    if "first second or third movement phase" not in norm:
        return None
    immediate_disembark = (
        "must immediately disembark after it has been set up on the battlefield" in norm
        or "must immediately disembark after this model has been set up on the battlefield" in norm
        or "must immediately disembark after it has been set up" in norm
        or "must immediately disembark after this model has been set up" in norm
    )
    if not immediate_disembark:
        return None
    m = re.search(r"set up more than (?P<dist>\d+) horizontally away from all enemy models", norm)
    if not m:
        m = re.search(r"set up more than (?P<dist>\d+) away from all enemy models", norm)
    if not m:
        return None
    notes = [
        "Must-start-in-Reserves transport can arrive in battle rounds 1-3 regardless of mission restrictions.",
    ]
    if (
        "not counted towards any limits placed on the maximum number of reserves units" in norm
        or "neither it nor any units embarked within it are counted towards any limits" in norm
    ):
        notes.append("Does not count towards reserves unit-count cap.")
    notes.append(
        f"Embarked units must immediately disembark after setup and be placed more than {m.group('dist')}\" from enemy models."
    )
    if "after this model has been set up on the battlefield no units can embark within it" in norm:
        notes.append("After setup, no units can embark within this transport.")
    return ("Supported", " ".join(notes))


