def _command_phase_bonus_cp_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    warlord_pattern = (
        r"(?:at the )?start of (?:each of )?your command phases? if .* your warlord and is on the battlefield "
        r"you gain (?P<cp>\d+) ?(?:cp|command points?)"
    )
    m_warlord = re.fullmatch(warlord_pattern, norm)
    if m_warlord:
        return (
            "Supported",
            f"Start of Command phase: gain {m_warlord.group('cp')} CP while this unit's named model is your WARLORD and on the battlefield.",
        )
    pattern = (
        r"(?:at the )?start of (?:each of )?your command phases? if (?:this model|this unit|the bearer) is on the battlefield "
        r"you gain (?P<cp>\d+) ?(?:cp|command points?)"
    )
    m = re.fullmatch(pattern, norm)
    if m:
        return ("Supported", f"Start of Command phase: gain {m.group('cp')} CP while on the battlefield.")
    end_roll_pattern = (
        r"at the end of your command phase(?: if (?:this model|this unit|the bearer) is on the battlefield)? "
        r"roll (?P<dice>\d+|one) d6 on a (?P<threshold>\d+) you gain (?P<cp>\d+) ?(?:cp|command points?)"
    )
    m_end = re.fullmatch(end_roll_pattern, norm)
    if not m_end:
        return None
    dice_token = str(m_end.group("dice") or "").strip().lower()
    dice_count = "1" if dice_token == "one" else dice_token
    return (
        "Supported",
        f"End of Command phase: roll {dice_count}D6; on {m_end.group('threshold')}+ gain {m_end.group('cp')} CP.",
    )


