def _command_phase_regain_wound_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    start_end_pattern = (
        r"(?:at the )?(?P<timing>start|end) of (?:(?:each|either) player(?: s|s) command phases?|(?:each of )?your command phases?) "
        r"this model regains (?:(?P<up_to>up to) )?(?P<amt>\d+|d3) lost wounds?"
    )
    m = re.fullmatch(start_end_pattern, norm)
    timing_label = ""
    if m:
        timing_label = "Start of Command phase" if str(m.group("timing") or "").strip().lower() == "start" else "End of Command phase"
    else:
        command_phase_pattern = (
            r"in (?:(?:each|either) player(?: s|s) command phases?|(?:each of )?your command phases?) "
            r"this model regains (?:(?P<up_to>up to) )?(?P<amt>\d+|d3) lost wounds?"
        )
        m = re.fullmatch(command_phase_pattern, norm)
        if not m:
            return None
        timing_label = "Command phase"
    amount = str(m.group("amt") or "").upper()
    if m.group("up_to"):
        return ("Supported", f"{timing_label}: this model regains up to {amount} lost wound(s).")
    return ("Supported", f"{timing_label}: this model regains {amount} lost wound(s).")


def _command_phase_unit_return_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    source_model_name = ""
    source_model_match = re.match(
        r"while this unit contains (?:one or more )?(?:a|an) (?P<source>[a-z0-9 ]+?)(?: models?)? "
        r"(?=(?:in your command phase|at the (?:start|end) of your command phase))",
        norm,
    )
    if source_model_match:
        source_model_name = str(source_model_match.group("source") or "").strip()
        norm = str(norm[source_model_match.end() :] or "").strip()
        if not norm:
            return None
    norm_with_context = norm
    amount_token = r"(one|a|\d+|(?:\d+)?d\d+(?:\s+\d+)?)"
    leading_clause = r"(?:while (?:this model|this unit|the bearer) is leading a unit )?"

    def _amount_label(token: str) -> str:
        token_l = str(token or "").strip().lower()
        if token_l in {"one", "a"}:
            return "1"
        if token_l.isdigit():
            return str(int(token_l))
        m_dice = re.fullmatch(r"(?:(?P<count>\d+))?d(?P<faces>\d+)(?:\s+(?P<modifier>\d+))?", token_l)
        if not m_dice:
            return token_l.upper()
        count = int(m_dice.group("count") or 1)
        faces = int(m_dice.group("faces") or 0)
        modifier = int(m_dice.group("modifier") or 0)
        if faces <= 0:
            return token_l.upper()
        label = f"{count}D{faces}" if count != 1 else f"D{faces}"
        if modifier > 0:
            label = f"{label}+{modifier}"
        return label
    targeted_model_pattern = (
        leading_clause
        +
        r"(?:in your command phase|(?:at the )?(?:start|end) of your command phase) "
        r"(?P<optional>you can )?select one friendly (?P<target_keyword>[a-z0-9 ]+) unit within (?P<range>\d+) of this model "
        r"and return(?: (?P<up_to>up to))? (?P<amt>"
        + amount_token
        + r") destroyed models? to that unit"
        r"(?: a (?P<limit_keyword>[a-z0-9 ]+) unit cannot be selected for this ability more than once per phase)?"
    )
    targeted_model = re.fullmatch(targeted_model_pattern, norm)
    if targeted_model:
        target_keyword = str(targeted_model.group("target_keyword") or "friendly").strip().upper()
        range_value = str(targeted_model.group("range") or "0")
        amount_label = _amount_label(str(targeted_model.group("amt") or ""))
        up_to_prefix = "up to " if targeted_model.group("up_to") else ""
        note = (
            f"Command phase: select one friendly {target_keyword} unit within {range_value}\"; "
            f"return {up_to_prefix}{amount_label} destroyed model(s) to that unit."
        )
        if bool(str(targeted_model.group("limit_keyword") or "").strip()):
            note = f"{note} Affected target units can only be selected once per phase."
        return ("Supported", note)
    targeted_unit_pattern = (
        leading_clause
        +
        r"(?:in your command phase|(?:at the )?(?:start|end) of your command phase) "
        r"select one friendly (?P<target_keyword>[a-z0-9 ]+) unit within (?P<range>\d+) of this unit "
        r"one destroyed model is returned to that (?P=target_keyword) unit for each (?P<count_keyword>[a-z0-9 ]+) model in this unit"
    )
    targeted = re.fullmatch(targeted_unit_pattern, norm)
    if targeted:
        target_keyword = str(targeted.group("target_keyword") or "friendly").strip().upper()
        count_keyword = str(targeted.group("count_keyword") or "source").strip().upper()
        range_value = str(targeted.group("range") or "0")
        return (
            "Supported",
            f"Command phase: select one friendly {target_keyword} unit within {range_value}\"; return one destroyed model to that unit for each {count_keyword} model in the source unit.",
        )
    if "bodyguard model" in norm or "bodyguard models" in norm:
        return None
    if "select one of the following" in norm:
        return None
    if "objective marker" in norm and "instead" in norm:
        return None
    alt_clause_match = re.search(
        r" if (?P<unit>this unit|the bearer s unit|the bearers unit) contains "
        r"(?P<count>one|a|an|two|three|four|five|six|\d+) models equipped with (?:a|an) (?P<wargear>[a-z0-9 ]+?) "
        r"return(?: (?P<alt_up_to>up to))? (?P<alt_amt>"
        + amount_token
        + r") destroyed (?P<alt_returned>.+?) to "
        r"(?:this unit|the bearer s unit|the bearers unit|that unit) instead$",
        norm,
    )
    base_norm = norm
    if alt_clause_match:
        base_norm = str(norm[:alt_clause_match.start()] or "").strip()
    target_unit_re = r"(?:this unit|the bearer s unit|the bearers unit|that unit)"
    pattern = (
        leading_clause
        +
        r"(?:in your command phase|(?:at the )?(?:start|end) of your command phase)"
        r"(?: if (?P<condition>[^,]+))? "
        r"you can return(?: (?P<up_to>up to))? (?P<amt>"
        + amount_token
        + r") destroyed (?P<returned>.+?) "
        r"to "
        + target_unit_re
    )
    m = re.fullmatch(pattern, base_norm)
    if not m:
        return None
    timing_label = "Command phase"
    if "start of your command phase" in base_norm:
        timing_label = "Start of Command phase"
    elif "end of your command phase" in base_norm:
        timing_label = "End of Command phase"
    leading_note = bool(
        re.search(r"while (?:this model|this unit|the bearer) is leading a unit", norm_with_context, flags=re.IGNORECASE)
    )
    amount_label = _amount_label(str(m.group("amt") or ""))
    up_to_prefix = "up to " if m.group("up_to") else ""
    returned_phrase = str(m.group("returned") or "").strip()
    if leading_note:
        note = f"{timing_label} while leading: return {up_to_prefix}{amount_label} destroyed model(s) to this/bearer's unit."
    else:
        note = f"{timing_label}: return {up_to_prefix}{amount_label} destroyed model(s) to this/bearer's unit."
    exclusion_phrase_match = re.search(
        r"\bexcluding\s+(?P<excluded>[a-z0-9 ]+?)\s+models?$",
        returned_phrase,
    )
    exclusion_phrase = str(exclusion_phrase_match.group("excluded") or "").strip() if exclusion_phrase_match else ""
    exclusion_labels: list[str] = []
    if "excluding character" in returned_phrase or "excluding character" in norm or re.search(r"\bcharacters?\b", exclusion_phrase):
        exclusion_labels.append("CHARACTER")
    if exclusion_phrase:
        for exclusion_part in re.split(r"\s*,\s*|\s+and\s+", exclusion_phrase):
            exclusion_name = str(exclusion_part or "").strip()
            if not exclusion_name:
                continue
            exclusion_name = re.sub(r"^(?:an?|the)\s+", "", exclusion_name).strip()
            if not exclusion_name or re.fullmatch(r"characters?", exclusion_name):
                continue
            exclusion_labels.append(exclusion_name.upper())
    if exclusion_labels:
        deduped_exclusion_labels: list[str] = []
        seen_exclusion_labels: set[str] = set()
        for exclusion_label in exclusion_labels:
            if exclusion_label in seen_exclusion_labels:
                continue
            seen_exclusion_labels.add(exclusion_label)
            deduped_exclusion_labels.append(exclusion_label)
        if len(deduped_exclusion_labels) == 1:
            exclusion_summary = deduped_exclusion_labels[0]
        elif len(deduped_exclusion_labels) == 2:
            exclusion_summary = f"{deduped_exclusion_labels[0]} and {deduped_exclusion_labels[1]}"
        else:
            exclusion_summary = f"{', '.join(deduped_exclusion_labels[:-1])}, and {deduped_exclusion_labels[-1]}"
        note = f"{note} Excludes {exclusion_summary} models."
    returned_clean = re.sub(r"\s+excluding\s+[a-z0-9 ]+?\s+models?$", "", returned_phrase).strip()
    named_return = re.sub(r"\s+models?$", "", returned_clean).strip()
    if named_return and named_return not in {"model", "models"}:
        note = f"{note} Restricted to destroyed {named_return.upper()}."
    if source_model_name:
        note = f"{note} Requires the unit to contain {source_model_name.upper()}."
    condition = str(m.group("condition") or "").strip()
    if "bearer is on the battlefield" in condition or "bearer is not destroyed" in condition:
        note = f"{note} Requires the bearer to be on the battlefield."
    if "below its starting strength" in condition and (
        "bearer s unit" in condition or "bearers unit" in condition or "this unit" in condition
    ):
        note = f"{note} Requires the bearer/unit to be below Starting Strength."
    if alt_clause_match:
        count_map = {
            "a": 1,
            "an": 1,
            "one": 1,
            "two": 2,
            "three": 3,
            "four": 4,
            "five": 5,
            "six": 6,
        }
        count_token = str(alt_clause_match.group("count") or "").strip().lower()
        count_label = str(count_map.get(count_token, count_token.upper() if count_token else ""))
        alt_wargear = str(alt_clause_match.group("wargear") or "").strip().upper()
        alt_amount_label = _amount_label(str(alt_clause_match.group("alt_amt") or ""))
        alt_up_to = "up to " if alt_clause_match.group("alt_up_to") else ""
        note = (
            f"{note} If the source unit has {count_label}+ model(s) equipped with {alt_wargear}, "
            f"return {alt_up_to}{alt_amount_label} instead."
        )
    return ("Supported", note)


