def _death_vision_of_sanguinius_support(name: str, description: str) -> Optional[Tuple[str, str]]:
    if _norm(name) != _norm("Death Vision of Sanguinius"):
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"if this model is destroyed by a melee attack after the attacking unit has finished making its attacks "
        r"you can roll one d6(?: adding (?P<bonus>\d+) to the result if the attacking unit contains the enemy warlord)? "
        r"on a (?P<low_min>\d+)\s+(?P<low_max>\d+) that enemy unit suffers (?P<low>\d+\s*d\d+(?:\s+\d+)?|d\d+(?:\s+\d+)?|\d+) mortal wounds "
        r"on a (?P<mid_min>\d+)\s+(?P<mid_max>\d+) that enemy unit suffers (?P<mid>\d+\s*d\d+(?:\s+\d+)?|d\d+(?:\s+\d+)?|\d+) mortal wounds "
        r"on a (?P<high_threshold>\d+)\+? that enemy unit suffers (?P<high>\d+\s*d\d+(?:\s+\d+)?|d\d+(?:\s+\d+)?|\d+) mortal wounds"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None

    def _expr(token: str) -> str:
        raw = re.sub(r"\s+", "", str(token or "").upper())
        if not raw:
            return ""
        dice_match = re.fullmatch(r"(?:(?P<count>\d+))?D(?P<faces>\d+)(?P<modifier>\d+)?", raw)
        if not dice_match:
            return raw
        count = int(dice_match.group("count") or 1)
        faces = int(dice_match.group("faces") or 0)
        modifier = int(dice_match.group("modifier") or 0)
        label = f"{count}D{faces}" if count != 1 else f"D{faces}"
        if modifier > 0:
            label = f"{label}+{modifier}"
        return label

    warlord_bonus = int(m.group("bonus") or 0)
    bonus_note = f", +{int(warlord_bonus)} if the attacking unit contains the enemy WARLORD" if warlord_bonus > 0 else ""
    return (
        "Supported",
        "Destroyed by a melee attack: after the attacker finishes its attacks, optional D6 roll"
        f"{bonus_note}; {m.group('low_min')}-{m.group('low_max')} deals {_expr(m.group('low'))}, "
        f"{m.group('mid_min')}-{m.group('mid_max')} deals {_expr(m.group('mid'))}, "
        f"{m.group('high_threshold')}+ deals {_expr(m.group('high'))} mortal wounds to the attacking unit.",
    )


def _battle_protocols_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"at the start of the battle if this model is leading a kastelan robots unit that unit enters aegis protocols(?: see below)? "
        r"in your command phase if this model is leading a kastelan robots unit you can select one protocol from those listed below for that unit to enter "
        r"once a unit enters a protocol it remains in that protocol until it enters a different one "
        r"protector protocol add (?P<ranged>\d+) to the attacks characteristic of ranged weapons equipped by kastelan robot models in that unit "
        r"conqueror protocol add (?P<melee>\d+) to the attacks characteristic of melee weapons equipped by kastelan robot models in that unit "
        r"aegis protocol add (?P<toughness>\d+) to the toughness characteristic of kastelan robot models in that unit"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None
    ranged = str(m.group("ranged") or "2")
    melee = str(m.group("melee") or "2")
    toughness = str(m.group("toughness") or "1")
    return (
        "Supported",
        f"Start of battle: led KASTELAN ROBOTS enter Aegis Protocol. Command phase selection supports Protector Protocol (+{ranged} ranged Attacks), Conqueror Protocol (+{melee} melee Attacks), and Aegis Protocol (+{toughness} Toughness for KASTELAN ROBOT models) until changed.",
    )


def _canticles_of_the_omnissiah_support(
    name: str,
    description: str,
    *,
    faction_id: str = "",
) -> Optional[Tuple[str, str]]:
    if not name:
        return None
    fid = str(faction_id or "").strip().upper()
    if fid and fid != "ADM":
        return None
    norm_name = _norm(name)
    norm_desc = _norm_rules_text(description or "")

    if norm_name == _norm("Canticles of the Omnissiah"):
        pattern = (
            r"(?:at the )?start of your command phase select one of the abilities in the canticles of the omnissiah section "
            r"until the start of your next command phase this model has that ability"
        )
        if re.fullmatch(pattern, norm_desc):
            return (
                "Supported",
                "Start of Command phase: select Invocation of Machine Vengeance, Mantra of Discipline, or Shroudpsalm until next Command phase.",
            )
        return None

    if norm_name == _norm("Invocation of Machine Vengeance"):
        pattern = (
            r"(?:at the )?start of your command phase select one unit from your opponents army "
            r"until the start of your next command phase that enemy unit is your machine vengeance target "
            r"each time a model in a friendly adeptus mechanicus unit makes an attack that targets your machine vengeance target "
            r"you can reroll the hit roll"
        )
        if re.fullmatch(pattern, norm_desc):
            return (
                "Supported",
                "Command phase target selection and Machine Vengeance hit re-roll vs selected enemy unit are implemented for friendly ADEPTUS MECHANICUS attacks.",
            )
        return None

    if norm_name == _norm("Mantra of Discipline"):
        pattern = (
            r"this model has the battleline keyword and has the following ability binharic courage aura "
            r"while a friendly adeptus mechanicus unit is within 6 of this model add 1 to the objective control characteristic of models in that unit "
            r"and each time you take a battle shock or leadership test for that unit add 1 to that test"
        )
        if re.fullmatch(pattern, norm_desc):
            return (
                "Supported",
                "When selected via Canticles, bearer gains BATTLELINE and friendly ADEPTUS MECHANICUS units within 6\" gain +1 Objective Control and +1 to Battle-shock/Leadership tests.",
            )
        return None

    if norm_name in {_norm("Shroudpsalm (Aura)"), _norm("Shroudpsalm")}:
        pattern = (
            r"while a friendly adeptus mechanicus unit is within 6 of this model "
            r"(?:that unit ha(?:s|ve)|models in that unit have) the stealth ability"
        )
        if re.fullmatch(pattern, norm_desc):
            return (
                "Supported",
                "When selected via Canticles, friendly ADEPTUS MECHANICUS units within 6\" gain Stealth.",
            )
        return None

    return None


def _start_shooting_phase_visible_battleshock_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"at the start of your shooting phase select one enemy unit within (?P<range>\d+) (?:of )?and visible to this model "
        r"that (?:enemy )?unit must take a battle shock test"
        r"(?: subtracting (?P<infantry_penalty>\d+) from the result if it is an infantry unit)?"
        r"(?: if the test is failed that (?:enemy )?unit suffers (?P<fail_mw>d3|d6|\d+) mortal wounds?)?"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None
    range_value = str(m.group("range") or "").strip()
    try:
        infantry_penalty = int(m.group("infantry_penalty") or 0)
    except (TypeError, ValueError):
        infantry_penalty = 0
    fail_mw_token = str(m.group("fail_mw") or "").strip().lower()
    details = [f"Start of Shooting phase: select a visible enemy unit within {range_value}\" to take a Battle-shock test."]
    if infantry_penalty > 0:
        details.append(f"INFANTRY targets take the test at -{int(infantry_penalty)}.")
    if fail_mw_token:
        if fail_mw_token.isdigit():
            details.append(f"On a failed test, that unit suffers {int(fail_mw_token)} mortal wounds.")
        else:
            details.append(f"On a failed test, that unit suffers {str(fail_mw_token).upper()} mortal wounds.")
    return (
        "Supported",
        " ".join(details),
    )


