def _opponent_command_phase_below_starting_battleshock_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    aura_range = 0
    aura_range_match = re.search(
        r"while an enemy unit(?: excluding [a-z0-9 ]+)? is within (?P<range>\d+) of this model",
        norm,
    )
    if aura_range_match:
        try:
            aura_range = int(aura_range_match.group("range") or 0)
        except (TypeError, ValueError):
            aura_range = 0
    leadership_worsen = 0
    leadership_match = re.search(
        r"worsen the leadership characteristic of models in that unit by (?P<val>\d+)",
        norm,
    )
    if leadership_match:
        try:
            leadership_worsen = int(leadership_match.group("val") or 0)
        except (TypeError, ValueError):
            leadership_worsen = 0
    pattern = (
        r"in the battle shock step of your opponent(?:s| s) command phase if "
        r"(?:an enemy unit that is below its starting strength is within (?P<range>\d+) of this model|"
        r"such an enemy unit is below its starting strength) "
        r"(?:that enemy unit|it) must take a battle shock test"
        r"(?P<suffix>(?: .+)?)"
    )
    m = re.search(pattern, norm)
    if not m:
        return None
    try:
        rng = int(m.group("range") or 0)
    except (TypeError, ValueError):
        rng = 0
    if rng <= 0:
        rng = int(max(0, aura_range))
    if rng <= 0:
        return None

    suffix = str(m.group("suffix") or "").strip()
    flat_penalty = 0
    psyker_penalty = 0
    if suffix:
        m_flat = re.fullmatch(
            r"subtracting (?P<val>\d+) from (?:(?:that|the) )?(?:test|result)(?: when it does so)?",
            suffix,
        )
        m_psyker = re.fullmatch(
            r"subtracting (?P<val>\d+) from that test if it is a psyker unit",
            suffix,
        )
        m_with = re.fullmatch(r"with (?P<val>\d+) to that test", suffix)
        if m_flat:
            try:
                flat_penalty = int(m_flat.group("val") or 0)
            except (TypeError, ValueError):
                flat_penalty = 0
        elif m_psyker:
            try:
                psyker_penalty = int(m_psyker.group("val") or 0)
            except (TypeError, ValueError):
                psyker_penalty = 0
        elif m_with:
            try:
                flat_penalty = int(m_with.group("val") or 0)
            except (TypeError, ValueError):
                flat_penalty = 0
        else:
            return None

    prefix = ""
    if leadership_worsen > 0:
        prefix = f"Enemy units within {rng}\" worsen Leadership by {leadership_worsen}. "

    if flat_penalty > 0:
        return (
            "Supported",
            f"{prefix}Opponent Command phase Battle-shock step: enemy units below Starting Strength within {rng}\" take Battle-shock tests at -{flat_penalty}.",
        )
    if psyker_penalty > 0:
        return (
            "Supported",
            f"{prefix}Opponent Command phase Battle-shock step: enemy units below Starting Strength within {rng}\" take Battle-shock tests; PSYKER units take the test at -{psyker_penalty}.",
        )
    return (
        "Supported",
        f"{prefix}Opponent Command phase Battle-shock step: enemy units below Starting Strength within {rng}\" take Battle-shock tests.",
    )


def _start_any_command_phase_objective_battleshock_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"once per battle at the start of any command phase you can select one objective marker within (?P<range>\d+) of the bearer "
        r"all enemy units(?: excluding (?P<exclude>[a-z0-9 ]+?))? within range of that objective marker must take a battle shock test"
        r"(?: each objective marker can only be targeted by this ability once per turn)?"
        r"(?: designers note .+)?"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None
    try:
        rng = int(m.group("range") or 0)
    except (TypeError, ValueError):
        rng = 0
    if rng <= 0:
        return None
    exclude_text = str(m.group("exclude") or "").strip().lower()
    exclude_monster_vehicle = (
        "monsters and vehicles" in exclude_text
        or "monster and vehicle" in exclude_text
    )
    once_per_turn = "each objective marker can only be targeted by this ability once per turn" in norm
    if exclude_monster_vehicle and once_per_turn:
        return (
            "Supported",
            f"Once per battle at start of any Command phase: select one objective marker within {rng}\" of the bearer; enemy non-MONSTER/VEHICLE units within range of that marker take Battle-shock tests; each objective marker can only be targeted once per turn.",
        )
    if exclude_monster_vehicle:
        return (
            "Supported",
            f"Once per battle at start of any Command phase: select one objective marker within {rng}\" of the bearer; enemy non-MONSTER/VEHICLE units within range of that marker take Battle-shock tests.",
        )
    if once_per_turn:
        return (
            "Supported",
            f"Once per battle at start of any Command phase: select one objective marker within {rng}\" of the bearer; enemy units within range of that marker take Battle-shock tests; each objective marker can only be targeted once per turn.",
        )
    return (
        "Supported",
        f"Once per battle at start of any Command phase: select one objective marker within {rng}\" of the bearer; enemy units within range of that marker take Battle-shock tests.",
    )


