def _start_selected_phases_enemy_range_battleshock_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"once per turn at the start of your (?P<phases>[a-z ]+?) phase(?:s)? "
        r"you can select one enemy unit within (?P<range>\d+) of this model "
        r"that(?: enemy)? unit must take a battle shock test "
        r"subtracting (?P<pen>\d+) from (?:(?:that|the) )?test(?: when it does so)?"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None
    try:
        rng = int(m.group("range") or 0)
    except (TypeError, ValueError):
        rng = 0
    try:
        pen = int(m.group("pen") or 0)
    except (TypeError, ValueError):
        pen = 0
    if rng <= 0 or pen <= 0:
        return None
    phases_raw = str(m.group("phases") or "").strip().lower()
    phase_tokens = [
        ("command", "Command"),
        ("movement", "Movement"),
        ("shooting", "Shooting"),
        ("charge", "Charge"),
        ("fight", "Fight"),
    ]
    phase_labels = [
        label
        for token, label in phase_tokens
        if re.search(rf"\b{re.escape(token)}\b", phases_raw)
    ]
    if not phase_labels:
        return None
    if len(phase_labels) == 1:
        phase_text = phase_labels[0]
    else:
        phase_text = ", ".join(phase_labels[:-1]) + f" or {phase_labels[-1]}"
    return (
        "Supported",
        f"Once per turn at the start of your {phase_text} phase: select one enemy unit within {rng}\" to take a Battle-shock test at -{pen}.",
    )


def _command_phase_enemy_range_battleshock_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    direct_pattern = (
        r"in your command phase (?:you can )?select one enemy unit within (?P<range>\d+) of "
        r"(?:this model|the bearer|this unit(?: s [a-z0-9 ]+ model)?) "
        r"that(?: enemy)? unit must take a battle shock test"
    )
    army_model_pattern = (
        r"in your command phase one model from your army with this ability can use it if it does "
        r"select one enemy unit within (?P<range>\d+) of it that(?: enemy)? unit must take a battle shock test"
    )
    direct_match = re.fullmatch(direct_pattern, norm)
    army_model_match = re.fullmatch(army_model_pattern, norm)
    if not direct_match and not army_model_match:
        return None
    try:
        rng = int((direct_match or army_model_match).group("range") or 0)
    except (TypeError, ValueError):
        rng = 0
    if rng <= 0:
        return None
    if army_model_match:
        return (
            "Supported",
            f"Command phase: one model from your army with this ability can select one enemy unit within {rng}\" of itself to take a Battle-shock test.",
        )
    return (
        "Supported",
        f"Command phase: select one enemy unit within {rng}\" of the source model to take a Battle-shock test.",
    )


