def _post_shoot_battleshock_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    heroic_pattern = (
        r"once per turn after one model from your army with this ability has shot you can select one "
        r"(?:(?P<infantry>infantry) )?(?:enemy )?unit hit by one or more of those attacks "
        r"that (?:enemy )?unit must take a battle shock test"
    )
    heroic_match = re.fullmatch(heroic_pattern, norm)
    if heroic_match:
        if heroic_match.group("infantry"):
            return (
                "Supported",
                "Once per turn after one model with this ability shoots, pick a hit enemy INFANTRY unit to take a Battle-shock test.",
            )
        return (
            "Supported",
            "Once per turn after one model with this ability shoots, pick a hit enemy unit to take a Battle-shock test.",
        )
    indirect_pattern = (
        r"in your shooting phase after this model has shot if one or more of those attacks made with an indirect fire weapon "
        r"scored a hit against an enemy unit that unit must take a battle shock test"
        r"(?: if an infantry unit is hit by one or more attacks made by a (?P<weapon>[a-z0-9 ]+) "
        r"they must subtract (?P<pen>\d+) from their battle shock test when doing so)?"
    )
    indirect_match = re.fullmatch(indirect_pattern, norm)
    if indirect_match:
        weapon_name = str(indirect_match.group("weapon") or "").strip()
        try:
            penalty = int(indirect_match.group("pen") or 0)
        except (TypeError, ValueError):
            penalty = 0
        if weapon_name and penalty > 0:
            return (
                "Supported",
                f"After shooting, each enemy unit hit by this model's Indirect Fire attacks takes a Battle-shock test; INFANTRY units hit by {weapon_name} take that test at -{int(penalty)}.",
            )
        return ("Supported", "After shooting, each enemy unit hit by this model's Indirect Fire attacks takes a Battle-shock test.")
    weapon_pattern = (
        r"in your shooting phase after this model has shot if one or more of those attacks made with "
        r"(?:a|an|the|its) (?P<weapon>[a-z0-9 ]+) scored a hit against an enemy "
        r"(?:(?P<infantry>infantry) )?unit that unit must take a battle shock test"
        r"(?: subtracting (?P<pen>\d+) from (?:(?:the )?result|that test))?"
    )
    weapon_match = re.fullmatch(weapon_pattern, norm)
    if weapon_match:
        weapon_name = str(weapon_match.group("weapon") or "").strip() or "this weapon"
        try:
            penalty = int(weapon_match.group("pen") or 0)
        except (TypeError, ValueError):
            penalty = 0
        if weapon_match.group("infantry"):
            if penalty > 0:
                return (
                    "Supported",
                    f"After shooting, an enemy INFANTRY unit hit by {weapon_name} must take a Battle-shock test at -{int(penalty)}.",
                )
            return (
                "Supported",
                f"After shooting, an enemy INFANTRY unit hit by {weapon_name} must take a Battle-shock test.",
            )
        if penalty > 0:
            return (
                "Supported",
                f"After shooting, an enemy unit hit by {weapon_name} must take a Battle-shock test at -{int(penalty)}.",
            )
        return ("Supported", f"After shooting, an enemy unit hit by {weapon_name} must take a Battle-shock test.")
    pattern = (
        r"in your shooting phase after this (?:model|unit) has shot (?:you can )?select one (?:enemy )?"
        r"(?:(?P<infantry>infantry) )?unit (?:that was )?hit by one or more of those attacks "
        r"(?:made with (?:(?:a|an|the|its|this model s|this unit s) )?[a-z0-9 ' -]+ )?"
        r"that (?:enemy )?unit must take a battle shock test"
        r"(?: subtracting (?P<pen>\d+) from (?:(?:the )?result|that test))?"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None
    try:
        penalty = int(m.group("pen") or 0)
    except (TypeError, ValueError):
        penalty = 0
    if m.group("infantry"):
        if penalty > 0:
            return ("Supported", f"After shooting, pick a hit enemy INFANTRY unit to take a Battle-shock test at -{int(penalty)}.")
        return ("Supported", "After shooting, pick a hit enemy INFANTRY unit to take a Battle-shock test.")
    if penalty > 0:
        return ("Supported", f"After shooting, pick a hit enemy unit to take a Battle-shock test at -{int(penalty)}.")
    return ("Supported", "After shooting, pick a hit enemy unit to take a Battle-shock test.")


