def _post_shoot_reactive_move_no_charge_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    alt_pattern = (
        r"in your shooting phase after this (?:model|model s unit|models unit|unit) has shot "
        r"if it is not within engagement range of (?:one or more|any) enemy units "
        r"(?:it|that unit|this unit|this model) can do one of the following "
        r"make a normal move of up to (?P<base_move>\d+) "
        r"make a normal move of up to (?P<battleline_move>\d+) "
        r"provided every model in this unit ends that move wholly within (?P<battleline_range>\d+) "
        r"of one or more friendly adeptus mechanicus battleline units "
        r"in either case if it does until the end of the turn (?:that unit|this unit|this model|it) is not eligible to declare a charge"
    )
    alt_match = re.fullmatch(alt_pattern, norm)
    if alt_match:
        try:
            base_move = int(alt_match.group("base_move") or 0)
        except (TypeError, ValueError):
            base_move = 0
        try:
            battleline_move = int(alt_match.group("battleline_move") or 0)
        except (TypeError, ValueError):
            battleline_move = 0
        try:
            battleline_range = int(alt_match.group("battleline_range") or 0)
        except (TypeError, ValueError):
            battleline_range = 0
        if base_move > 0 and battleline_move > 0 and battleline_range > 0:
            return (
                "Supported",
                f"After shooting (if not in Engagement Range): choose one Normal move option ({base_move}\" base, or {battleline_move}\" while ending wholly within {battleline_range}\" of friendly ADEPTUS MECHANICUS BATTLELINE); cannot charge this turn.",
            )

    required_pattern = (
        r"in your shooting phase after this (?:model|model s unit|models unit|unit) has shot "
        r"if it contains an? (?P<model>[a-z0-9 \-]+?) equipped with an? (?P<wargear>[a-z0-9 \-]+?) "
        r"(?:it|that unit|this unit|this model) can make a normal move(?: of up to (?P<move>d6|\d+))?"
        r"(?: as if it were your movement phase)? "
        r"if it does(?: so)? until the end of the turn (?:that unit|this unit|this model|it) is not eligible to declare a charge"
    )
    required_match = re.fullmatch(required_pattern, norm)
    if required_match:
        move = str(required_match.group("move") or "").strip().upper()
        move_label = "its Move characteristic" if not move else ("D6" if move == "D6" else move)
        if not move:
            move_note = "using its Move characteristic"
        else:
            move_note = f"of up to {move_label}\""
        model_name = str(required_match.group("model") or "model").strip().upper()
        wargear_name = str(required_match.group("wargear") or "wargear").strip().upper()
        return (
            "Supported",
            f"After shooting, this unit can make a Normal move {move_note} and then cannot charge this turn, but only while it contains a {model_name} equipped with {wargear_name}.",
        )

    pattern = (
        r"in your shooting phase after this (?:model|model s unit|models unit|unit) has shot"
        r"(?: if it is not within engagement range of (?:one or more|any) enemy units)? "
        r"(?:it|that unit|this unit|this model) can make a normal move(?: of up to (?P<move>d6|\d+))?"
        r"(?: as if it were your movement phase)? "
        r"if it does(?: so)? until the end of the turn (?:that unit|this unit|this model|it) is not eligible to declare a charge"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None
    move = str(m.group("move") or "").strip().upper()
    move_label = "its Move characteristic" if not move else ("D6" if move == "D6" else move)
    gated = "if it is not within engagement range" in norm
    note = f"After shooting: this unit can make a Normal move of up to {move_label}\" and then cannot charge this turn."
    if not move:
        note = "After shooting: this unit can make a Normal move using its Move characteristic and then cannot charge this turn."
    if gated:
        note = f"After shooting (if not in Engagement Range): this unit can make a Normal move of up to {move_label}\" and then cannot charge this turn."
    if gated and not move:
        note = "After shooting (if not in Engagement Range): this unit can make a Normal move using its Move characteristic and then cannot charge this turn."
    return ("Supported", note)


def _post_shoot_no_cover_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"(?:(?:in your shooting phase (?:(?:each time )?this (?:model|unit) is selected to shoot )?)?"
        r"(?:after (?:this (?:model|unit) has shot|resolving (?:its|those) attacks)|each time this (?:model|unit) has shot)) "
        r"select one enemy unit (?:that was )?hit by one or more "
        r"(?:of those attacks|attacks made by this (?:model|unit) this phase) "
        r"(?:made with (?:a|an|the|its) (?P<weapon>[a-z0-9 ]+) )?"
        r"until the (?P<duration>end of the phase|start of your next shooting phase) "
        r"that (?:enemy )?unit cannot have the benefit of cover"
    )
    m = re.fullmatch(pattern, norm)
    if m is None:
        m = re.fullmatch(
            r"(?:(?:in your shooting phase (?:(?:each time )?this (?:model|unit) is selected to shoot )?)?"
            r"(?:after (?:this (?:model|unit) has shot|resolving (?:its|those) attacks)|each time this (?:model|unit) has shot)) "
            r"select one enemy unit (?:that was )?hit by one or more "
            r"(?:of those attacks|attacks made by this (?:model|unit) this phase) "
            r"(?:made with (?:a|an|the|its) (?P<weapon>[a-z0-9 ]+) )?"
            r"until the (?P<duration>end of the phase|start of your next shooting phase) that unit is (?P<state>[a-z0-9 -]+) "
            r"while a unit is (?P=state) it cannot have the benefit of cover",
            norm,
        )
    if not m:
        return None
    weapon = str(m.group("weapon") or "").strip()
    duration = str(m.group("duration") or "").strip().lower()
    if "start of your next shooting phase" in duration:
        if weapon:
            return (
                "Supported",
                f"After shooting: select a hit enemy unit hit by {weapon}; it cannot gain Benefit of Cover until your next Shooting phase.",
            )
        return (
            "Supported",
            "After shooting: select a hit enemy unit; it cannot gain Benefit of Cover until your next Shooting phase.",
        )
    if weapon:
        return ("Supported", f"After shooting: select a hit enemy unit hit by {weapon}; it cannot gain Benefit of Cover until phase end.")
    return ("Supported", "After shooting: select a hit enemy unit; it cannot gain Benefit of Cover until phase end.")


