def _curse_of_the_wulfen_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"while this unit is within (?P<char_range>\d+) of one or more friendly (?P<char_keyword>[a-z0-9 ]+) models "
        r"excluding (?P<char_exclude>[a-z0-9 ]+) models or within (?P<priest_range>\d+) of one or more friendly "
        r"(?P<priest_keyword>[a-z0-9 ]+) models if it is not battle shocked add (?P<infantry_bonus>\d+) to the "
        r"objective control characteristic of (?P<infantry_keyword>[a-z0-9 ]+) models in it and add "
        r"(?P<vehicle_bonus>\d+) to the objective control characteristic of (?P<vehicle_keyword>[a-z0-9 ]+) models in it"
    )
    match = re.fullmatch(pattern, norm)
    if not match:
        return None
    try:
        char_range = int(match.group("char_range") or 0)
        priest_range = int(match.group("priest_range") or 0)
        infantry_bonus = int(match.group("infantry_bonus") or 0)
        vehicle_bonus = int(match.group("vehicle_bonus") or 0)
    except (TypeError, ValueError):
        return None
    if min(char_range, priest_range, infantry_bonus, vehicle_bonus) <= 0:
        return None
    char_keyword = re.sub(r"\s+", " ", str(match.group("char_keyword") or "").strip()).upper()
    char_exclude = re.sub(r"\s+", " ", str(match.group("char_exclude") or "").strip()).upper()
    priest_keyword = re.sub(r"\s+", " ", str(match.group("priest_keyword") or "").strip()).upper()
    infantry_keyword = re.sub(r"\s+", " ", str(match.group("infantry_keyword") or "").strip()).upper()
    vehicle_keyword = re.sub(r"\s+", " ", str(match.group("vehicle_keyword") or "").strip()).upper()
    if not all((char_keyword, char_exclude, priest_keyword, infantry_keyword, vehicle_keyword)):
        return None
    return (
        "Supported",
        f"While non-Battle-shocked, models in this unit gain +{int(infantry_bonus)} Objective Control if they are {infantry_keyword} while within {int(char_range)}\" of friendly {char_keyword} models excluding {char_exclude}, or within {int(priest_range)}\" of friendly {priest_keyword} models; {vehicle_keyword} models in this unit gain +{int(vehicle_bonus)} Objective Control instead.",
    )


def _black_rage_support(
    name: str,
    description: str,
    *,
    faction_id: str = "",
) -> Optional[Tuple[str, str]]:
    if _norm(name) != "black rage":
        return None
    fid = str(faction_id or "").strip().upper()
    if fid and fid != "SM":
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"each time this model makes a melee attack you can reroll the hit roll "
        r"while this models unit is not within (?P<char_range>\d+) of one or more friendly "
        r"(?P<char_keyword>[a-z0-9 ]+?) models or (?P<chaplain_range>\d+) of one or more friendly "
        r"(?P<chaplain_keyword>[a-z0-9 ]+?) models it cannot be selected to fall back "
        r"and its objective control characteristic is (?P<objective_control>\d+)"
    )
    match = re.fullmatch(pattern, norm)
    if not match:
        return None
    try:
        char_range = int(match.group("char_range") or 0)
        chaplain_range = int(match.group("chaplain_range") or 0)
        objective_control = int(match.group("objective_control") or 0)
    except (TypeError, ValueError):
        return None
    char_keyword = re.sub(r"\s+", " ", str(match.group("char_keyword") or "").strip()).upper()
    chaplain_keyword = re.sub(r"\s+", " ", str(match.group("chaplain_keyword") or "").strip()).upper()
    if char_range <= 0 or chaplain_range <= 0 or objective_control < 0:
        return None
    if not char_keyword or not chaplain_keyword:
        return None
    oc_note = f"Objective Control {int(objective_control)}" if int(objective_control) != 0 else "Objective Control 0"
    return (
        "Supported",
        f"Black Rage models can re-roll melee Hit rolls. While their unit is not within {int(char_range)}\" of friendly {char_keyword} models or {int(chaplain_range)}\" of friendly {chaplain_keyword} models, those models have {oc_note} and their unit cannot be selected to Fall Back.",
    )


def _command_phase_psychic_veil_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"in your command phase this psyker can use this ability if it does roll (?:one|1) d6 "
        r"on a 1 this psyker(?: s|s) unit suffers d3 mortal wounds on a 2\+? until the start of your next command phase "
        r"this psyker(?: s|s) unit can only be selected as the target of a ranged attack if the attacking model is within (?P<range>\d+)"
        r"(?: designer(?:s| s)? note .+)?"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None
    try:
        range_value = int(m.group("range") or 0)
    except (TypeError, ValueError):
        range_value = 0
    if range_value <= 0:
        return None
    return (
        "Supported",
        f"Command phase optional activation: roll D6; on 1 this PSYKER's unit suffers D3 mortal wounds, on 2+ it can only be targeted by ranged attacks from within {int(range_value)}\" until your next Command phase.",
    )


