def _seed_spore_mines_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"once per turn in your shooting phase when selected to shoot one unit with this ability can use it instead of making any attacks with its ranged weapons "
        r"if it does you can add one new (?P<spawn>[a-z0-9 ]+?) unit(?: containing (?P<count_expr>d\d+|\d+) models?)? to your army "
        r"and set it up anywhere on the battlefield that is wholly within (?P<setup>\d+) of this (?P<scope>model|unit) "
        r"and more than (?P<enemy>\d+) horizontally away from all enemy units"
        r"(?: that [a-z0-9 ]+)?"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None

    spawn_name = " ".join(str(m.group("spawn") or "").strip().split())
    if not spawn_name:
        return None
    try:
        setup_range = int(m.group("setup") or 0)
    except (TypeError, ValueError):
        setup_range = 0
    try:
        enemy_range = int(m.group("enemy") or 0)
    except (TypeError, ValueError):
        enemy_range = 0
    if setup_range <= 0 or enemy_range <= 0:
        return None
    scope = str(m.group("scope") or "unit").strip().lower() or "unit"

    count_expr = str(m.group("count_expr") or "").strip().upper()
    if "contains 1 model for each model in this unit" in norm:
        count_note = "with 1 spawned model per source-unit model"
    elif count_expr:
        count_note = f"containing {count_expr} model(s)"
    else:
        count_note = "with parsed model count"

    return (
        "Supported",
        (
            f"Shooting phase optional replacement: select one unit with this ability to spawn a new {spawn_name} unit {count_note}; "
            f"setup enforces wholly within {int(setup_range)}\" of the source {scope} and more than {int(enemy_range)}\" horizontally from enemy units, "
            "with deterministic setup-point decisions and spawned-unit placement validation."
        ),
    )


def _post_shoot_ap_bonus_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"(?:in your shooting phase after this|each time this) (?:model|unit) has shot select one enemy unit "
        r"(?:excluding monsters and vehicles )?hit by one or more of those attacks "
        r"(?:made with (?:its|this model s) (?P<weapon>[a-z0-9 ]+) )?"
        r"until the end of the (?P<duration>phase|turn) each time a friendly (?P<keyword>[a-z0-9 ]+?) unit makes (?:a|an) "
        r"(?:(?P<atype>ranged|melee) )?attack that targets that enemy unit improve the armour penetration characteristic "
        r"of that attack by (?P<val>\d+)(?: the same enemy unit can only be affected by this ability once per (?:turn|phase)"
        r"| each unit can only be selected for this ability once per turn)?"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None
    keyword = str(m.group("keyword") or "").strip().upper()
    atype = str(m.group("atype") or "").strip().lower()
    try:
        val = int(m.group("val") or 0)
    except Exception:
        val = 0
    if val <= 0:
        return None
    duration = str(m.group("duration") or "phase").strip().lower() or "phase"
    scope = "attacks"
    if atype == "ranged":
        scope = "ranged attacks"
    elif atype == "melee":
        scope = "melee attacks"
    duration_note = "until phase end" if duration == "phase" else "until turn end"
    note = f"After shooting: select a hit enemy unit; friendly {keyword} {scope} against it gain AP +{val} {duration_note}."
    weapon = str(m.group("weapon") or "").strip()
    if weapon:
        note = f"After shooting: select a hit enemy unit hit by {weapon}; friendly {keyword} {scope} against it gain AP +{val} {duration_note}."
    if "excluding monsters and vehicles" in norm:
        note = f"After shooting: select a hit enemy unit (not MONSTER/VEHICLE); friendly {keyword} {scope} against it gain AP +{val} {duration_note}."
        if weapon:
            note = f"After shooting: select a hit enemy unit (not MONSTER/VEHICLE) hit by {weapon}; friendly {keyword} {scope} against it gain AP +{val} {duration_note}."
    if "once per turn" in norm:
        note += " Target limit: once per turn."
    elif "once per phase" in norm:
        note += " Target limit: once per phase."
    return ("Supported", note)


