def _fight_phase_aura_battleshock_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"at the start of the fight phase (?:each|every) enemy unit"
        r"(?: excluding (?P<exclude>[a-z0-9 ]+?))? within (?P<range>\d+) of this model must take a battle shock test"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None
    try:
        rng = int(m.group("range") or 0)
    except Exception:
        rng = 0
    if rng <= 0:
        return None
    note = f"Start of Fight phase: enemy units within {rng}\" take a Battle-shock test."
    exclude_raw = str(m.group("exclude") or "").strip()
    if exclude_raw:
        tokens = []
        for token in re.split(r"\band\b|,", exclude_raw):
            t = str(token or "").strip().upper()
            if t:
                tokens.append(t)
        if tokens:
            note = f"Start of Fight phase: enemy units within {rng}\" (excluding {', '.join(tokens)}) take a Battle-shock test."
    return ("Supported", note)


def _post_fight_destroyed_aura_battleshock_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    model_pattern = (
        r"each time this model is selected to fight after resolving its attacks if one or more enemy units were destroyed by those attacks "
        r"each enemy unit within (?P<range>\d+) of this model must take a battle shock test"
    )
    unit_pattern = (
        r"each time this models unit has fought if one or more enemy units were destroyed as a result of those attacks "
        r"each enemy unit within (?P<range>\d+) of this model must take a battle shock test"
    )
    m = re.fullmatch(model_pattern, norm)
    unit_destroy_trigger = False
    if not m:
        m = re.fullmatch(unit_pattern, norm)
        unit_destroy_trigger = m is not None
    if not m:
        return None
    try:
        rng = int(m.group("range") or 0)
    except (TypeError, ValueError):
        rng = 0
    if rng <= 0:
        return None
    return (
        "Supported",
        (
            f"After this model's unit fights, if its attacks destroyed one or more enemy units, each enemy unit within {rng}\" of this model takes a Battle-shock test."
            if unit_destroy_trigger
            else f"After this model fights, if its attacks destroyed one or more enemy units, each enemy unit within {rng}\" takes a Battle-shock test."
        ),
    )


def _charge_end_engagement_battleshock_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"each time this (?:model s )?unit ends a charge move each enemy unit within engagement range of (?:that|this) unit must take a battle shock test"
    )
    match = re.search(pattern, norm)
    if not match:
        return None
    note_parts = []
    if "reroll charge rolls made for this unit" in norm:
        note_parts.append("Charge rolls made for this unit can be re-rolled.")
    note_parts.append("After this unit ends a Charge move, engaged enemy units take Battle-shock tests.")
    conditional_match = re.search(
        r"if that enemy unit does not have the (?P<keywords>[a-z0-9 \-]+?(?: or [a-z0-9 \-]+)*) keywords subtract (?P<penalty>\d+) from that test",
        norm,
    )
    if conditional_match:
        keywords = str(conditional_match.group("keywords") or "").strip().upper().replace(" OR ", "/")
        penalty = str(conditional_match.group("penalty") or "0")
        note_parts.append(f"Targets without {keywords} take the test at -{penalty}.")
    return ("Supported", " ".join(note_parts))


def _start_any_phase_tome_skull_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"once per battle for each tome skull this unit is equipped with at the start of any phase you can select either one friendly "
        r"(?P<keyword>[a-z0-9 ]+?) unit that is battle shocked and within (?P<range>\d+) of this unit "
        r"or one enemy unit within (?P<enemy_range>\d+) of this unit "
        r"if you select a friendly unit that unit is no longer battle shocked if you select an enemy unit it must take a battle shock test"
        r"(?: designers note .+)?"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None
    try:
        rng = int(m.group("range") or 0)
    except (TypeError, ValueError):
        rng = 0
    try:
        enemy_rng = int(m.group("enemy_range") or 0)
    except (TypeError, ValueError):
        enemy_rng = 0
    if rng <= 0 or enemy_rng <= 0:
        return None
    if rng != enemy_rng:
        return None
    keyword = str(m.group("keyword") or "").strip()
    keyword_label = keyword.upper() if keyword else "friendly"
    return (
        "Supported",
        f"Once per battle for each Tome-skull: start of any phase, either clear Battle-shock on a {keyword_label} unit within {rng}\" or select an enemy unit within {rng}\" to take a Battle-shock test.",
    )


def _start_any_phase_battleshock_clear_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"once per battle(?: round)? at the start of any phase you can select one friendly (?P<keyword>[a-z0-9 ]+?) unit that is battle shocked "
        r"and within (?P<range>\d+) of (?:this model|the bearer|this unit s (?P<model>[a-z0-9 ]+?) model) "
        r"(?:(?:if you do )?(?:(?:destroy|destroying) (?P<destroy_count>one|\d+) model in that unit and |(?P<destroy_count_post>one|\d+) model in that unit is destroyed and ))?"
        r"that unit is (?:then )?no longer battle shocked"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None
    try:
        rng = int(m.group("range") or 0)
    except Exception:
        rng = 0
    if rng <= 0:
        return None
    keyword = str(m.group("keyword") or "").strip()
    keyword_label = keyword.upper() if keyword else "friendly"
    destroy_count_raw = str(m.group("destroy_count") or m.group("destroy_count_post") or "").strip().lower()
    destroy_count = 1 if destroy_count_raw == "one" else int(destroy_count_raw) if destroy_count_raw.isdigit() else 0
    once_text = "Once per battle round" if "once per battle round" in norm else "Once per battle"
    note = f"{once_text}, start of any phase: clear Battle-shock on a {keyword_label} unit within {rng}\"."
    if destroy_count > 0:
        plural = "s" if destroy_count != 1 else ""
        note = (
            f"{once_text}, start of any phase: select a Battle-shocked {keyword_label} unit within {rng}\", "
            f"destroy {destroy_count} model{plural} in that unit, then clear Battle-shock."
        )
    return ("Supported", note)


