def _return_on_death_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    pattern = (
        r"the first time (?:this model|the bearer) is destroyed(?: remove it from play without resolving its deadly demise ability)?(?: then)? "
        r"(?:at the end of the phase roll one d6|roll one d6 at the end of the phase) on a (?P<roll>\d+) "
        r"set (?:this model|the bearer) back up on the battlefield(?: as close as possible to where it was destroyed)? "
        r"and not within engagement range of (?:one or more|any) enemy (?:units|models) with "
        r"(?P<wounds>its full wounds remaining|(?:d3|d6|\d+) wounds? remaining)"
    )
    m = re.fullmatch(pattern, norm)
    if not m:
        return None
    roll = m.group("roll") or "2"
    wounds_raw = m.group("wounds") or ""
    wounds_desc = "full wounds"
    if "full wounds" in wounds_raw:
        wounds_desc = "full wounds"
    elif wounds_raw.startswith("d3"):
        wounds_desc = "D3 wounds"
    elif wounds_raw.startswith("d6"):
        wounds_desc = "D6 wounds"
    else:
        m2 = re.search(r"\d+", wounds_raw)
        if m2:
            wounds_desc = f"{m2.group(0)} wounds"
    return (
        "Supported",
        f"First time destroyed: roll D6 at end of phase; on {roll}+ return with {wounds_desc} (not within Engagement Range).",
    )


def _shoot_on_death_after_attacks_support(description: str) -> Optional[Tuple[str, str]]:
    if not description:
        return None
    norm = _norm_rules_text(description)
    if not norm:
        return None
    m = re.fullmatch(
        r"when this model is destroyed roll one d6 on a (?P<threshold>\d)\+? do not remove it from play "
        r"(?:it|this model) can after the attacking (?:unit|model'?s unit|model s unit|models unit) has finished making its attacks "
        r"shoot as if it were your shooting phase(?: and as if it had its full wounds remaining)? this model is then removed from play"
        r"(?: when resolving these attacks any hazardous tests taken for that attack are automatically passed)?",
        norm,
    )
    if m:
        note = (
            f"Shoot-on-death: roll D6 on destruction; on {m.group('threshold')}+ this model shoots after the attacker finishes its attacks."
        )
        if "full wounds remaining" in norm:
            note += " Shooting is resolved as if the model had full wounds remaining."
        if "when resolving these attacks any hazardous tests taken for that attack are automatically passed" in norm:
            note += " Those return shots auto-pass Hazardous tests and only trigger when destroyed by an attack or Hazardous test."
        return ("Supported", note)
    m = re.fullmatch(
        r"each time a model in (?:this|that) unit is destroyed roll one d6 on a (?P<threshold>\d)\+? do not remove it from play "
        r"the destroyed model can shoot after the attacking (?:unit|model'?s unit|model s unit|models unit) has finished making its attacks "
        r"and is then removed from play(?: when resolving these attacks any hazardous tests taken for that attack are automatically passed)?",
        norm,
    )
    if m:
        note = (
            f"Shoot-on-death: roll D6 on destruction; on {m.group('threshold')}+ the destroyed model shoots after the attacker finishes its attacks."
        )
        if "when resolving these attacks any hazardous tests taken for that attack are automatically passed" in norm:
            note += " Those return shots auto-pass Hazardous tests and only trigger when destroyed by an attack or Hazardous test."
        return ("Supported", note)
    m = re.fullmatch(
        r"while the (?P<required>[a-z0-9 '\-]+?) model is on the battlefield each time a (?P<destroyed>[a-z0-9 '\-]+?) model "
        r"is destroyed roll one d6 on a (?P<threshold>\d)\+? do not remove it from play the destroyed model can shoot after the "
        r"attacking (?:unit|model'?s unit|model s unit|models unit) has finished making its attacks and is then removed from play",
        norm,
    )
    if not m:
        return None
    return (
        "Supported",
        f"Shoot-on-death: while the {str(m.group('required') or '').upper()} model is on the battlefield, destroyed {str(m.group('destroyed') or '').upper()} models roll D6 and shoot after attacks on {m.group('threshold')}+.",
    )


